import os
from mindee import Client
from mindee.product import ReceiptV5

def extract_receipt_fields(image_path: str) -> dict:
    api_key = os.getenv("MINDEE_API_KEY")
    if not api_key:
        raise ValueError("MINDEE_API_KEY environment variable is required")

    client = Client(api_key=api_key)
    input_document = client.doc_from_path(image_path)

    response = client.parse(ReceiptV5, input_document)
    prediction = response.document.inference.prediction

    merchant = prediction.merchant_name.value or ""
    total_amount = prediction.total_amount.value or 0.0

    tax_amount = 0.0
    if prediction.taxes.value:
        tax_amount = sum(tax.amount for tax in prediction.taxes.value)

    items = []
    if prediction.line_items:
        for item in prediction.line_items:
            items.append({
                "description": item.description or "",
                "quantity": item.quantity or 0,
                "total": item.total_amount or 0.0
            })

    return {
        "merchant": merchant,
        "tax": tax_amount,
        "total": total_amount,
        "items": items
    }
